import type { Client } from "../../types/workforce"
import type { ClientFigures } from "./client-figures"

/**
 * The clients list's own filters and grouping (CRM step 10): conditions joined
 * by AND (all must match) or OR (any may match), and one field to group rows by.
 */

/** Fields chosen from a list of values */
export const CHOICE_FIELDS = ["status", "manager", "industry", "tag", "leadSource", "health", "country"] as const
/** Fields compared with a number */
export const NUMBER_FIELDS = ["owed", "overdue", "openDeals", "projects", "daysSinceContact"] as const
/** Amounts, only offered to people who may read invoices */
export const MONEY_FIELDS: readonly FilterField[] = ["owed", "overdue"]

export type ChoiceField = (typeof CHOICE_FIELDS)[number]
export type NumberField = (typeof NUMBER_FIELDS)[number]
export type FilterField = ChoiceField | NumberField
export type FilterOp = "is" | "isNot" | "isEmpty" | "isNotEmpty" | "gt" | "lt"

export const CHOICE_OPS: readonly FilterOp[] = ["is", "isNot", "isEmpty", "isNotEmpty"]
export const NUMBER_OPS: readonly FilterOp[] = ["gt", "lt"]

export interface FilterCondition {
  id: string
  field: FilterField
  op: FilterOp
  value?: string
}

export interface AdvancedFilter {
  /** all: every condition must match (AND); any: one is enough (OR) */
  mode: "all" | "any"
  conditions: FilterCondition[]
}

export const EMPTY_FILTER: AdvancedFilter = { mode: "all", conditions: [] }

export const isNumberField = (f: FilterField): f is NumberField => (NUMBER_FIELDS as readonly string[]).includes(f)
export const opsFor = (f: FilterField) => (isNumberField(f) ? NUMBER_OPS : CHOICE_OPS)

/** Whole days between two yyyy-mm-dd dates. */
const daysBetween = (from: string, to: string) => Math.round((Date.parse(`${to}T00:00:00Z`) - Date.parse(`${from}T00:00:00Z`)) / 86_400_000)

/** The values a client holds for a choice field (several for tags). */
export function choiceValues(c: Client, f: ClientFigures | undefined, field: ChoiceField): string[] {
  switch (field) {
    case "status": return [c.status]
    case "manager": return c.accountManagerId ? [c.accountManagerId] : []
    case "industry": return c.industry ? [c.industry] : []
    case "tag": return c.tags ?? []
    case "leadSource": return c.leadSource ? [c.leadSource] : []
    case "health": return f?.health ? [f.health.level] : []
    case "country": return c.country ? [c.country] : []
  }
}

/** A client's number for a number field; no contact yet counts as forever. */
export function numberValue(_c: Client, f: ClientFigures | undefined, field: NumberField, today: string): number {
  switch (field) {
    case "owed": return f?.outstanding ?? 0
    case "overdue": return f?.overdue ?? 0
    case "openDeals": return f?.openDeals.count ?? 0
    case "projects": return f?.projects.total ?? 0
    case "daysSinceContact": return f?.lastContact ? daysBetween(f.lastContact, today) : Number.POSITIVE_INFINITY
  }
}

/** A condition is used once it says what to compare with (empty / not empty need no value). */
export function isComplete(c: FilterCondition) {
  if (c.op === "isEmpty" || c.op === "isNotEmpty") return true
  if (isNumberField(c.field)) return c.value !== undefined && c.value !== "" && Number.isFinite(Number(c.value))
  return !!c.value
}

export function matchesCondition(c: Client, f: ClientFigures | undefined, cond: FilterCondition, today: string): boolean {
  if (isNumberField(cond.field)) {
    const n = numberValue(c, f, cond.field, today)
    const v = Number(cond.value)
    return cond.op === "gt" ? n > v : n < v
  }
  const values = choiceValues(c, f, cond.field)
  switch (cond.op) {
    case "is": return values.includes(cond.value!)
    case "isNot": return !values.includes(cond.value!)
    case "isEmpty": return values.length === 0
    case "isNotEmpty": return values.length > 0
    default: return true
  }
}

/** True when the client passes the filter; unfinished conditions are ignored, no condition passes everyone. */
export function matchesFilter(c: Client, f: ClientFigures | undefined, filter: AdvancedFilter, today: string): boolean {
  const used = filter.conditions.filter(isComplete)
  if (used.length === 0) return true
  return filter.mode === "all" ? used.every((x) => matchesCondition(c, f, x, today)) : used.some((x) => matchesCondition(c, f, x, today))
}

/** Fields the list can be grouped by */
export const GROUP_FIELDS = ["status", "manager", "industry", "leadSource", "health", "country"] as const satisfies readonly ChoiceField[]
export type GroupField = (typeof GROUP_FIELDS)[number]

/** The group a client falls in; "" when the field is empty. */
export function groupKey(c: Client, f: ClientFigures | undefined, field: GroupField): string {
  return choiceValues(c, f, field)[0] ?? ""
}

/** Reads a filter kept in a saved view, ignoring anything that is not one. */
export function readFilter(value: unknown): AdvancedFilter {
  if (!value || typeof value !== "object") return EMPTY_FILTER
  const v = value as Partial<AdvancedFilter>
  const fields = [...CHOICE_FIELDS, ...NUMBER_FIELDS] as readonly string[]
  const ops = [...CHOICE_OPS, ...NUMBER_OPS] as readonly string[]
  const conditions = Array.isArray(v.conditions)
    ? v.conditions.filter((c): c is FilterCondition => !!c && typeof c.id === "string" && fields.includes(c.field) && ops.includes(c.op))
    : []
  return { mode: v.mode === "any" ? "any" : "all", conditions }
}
